class ModelNew(nn.Module):
    """
    Layer Normalization implemented with a single cooperative CuTe/CUDA kernel.
    The nn.LayerNorm member is retained for parameter compatibility, while all
    forward computation is performed by the custom kernel.
    """
    def __init__(self, normalized_shape: tuple):
        super(ModelNew, self).__init__()
        self.ln = nn.LayerNorm(normalized_shape=normalized_shape)
        self._ext = cute_layernorm_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.layernorm_forward(
            x.contiguous(),
            self.ln.weight.contiguous(),
            self.ln.bias.contiguous(),
            float(self.ln.eps),
        )
